    enonce: "نعتبر العبارة <span dir=\"ltr\" class=\"expr\">P = x</span><sup>2</sup> <span dir=\"ltr\" class=\"expr\">− 14x + 45.</span><br>فكّك العبارة <span dir=\"ltr\" class=\"expr\">P</span> إلى جداء عاملين من الدرجة الأولى.",
    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr\">P = x</span><sup>2</sup><span dir=\"ltr\" class=\"expr\"> − 14x + 45</span>"},{"quoi":"القاعدة","math":"إكمال المربّع <span dir=\"ltr\" class=\"expr\">: x</span><sup>2</sup> <span dir=\"ltr\" class=\"expr\">− 2ax = (x − a)</span><sup>2</sup> <span dir=\"ltr\" class=\"expr\">− a</span><sup>2</sup>"},{"quoi":"نطبّق","math":"نصف معامل <span dir=\"ltr\" class=\"expr\">x</span> هو <span dir=\"ltr\" class=\"expr\">7</span> ، إذن <span dir=\"ltr\" class=\"expr\">P = (x − 7)</span><sup>2</sup> <span dir=\"ltr\" class=\"expr\">− 49 + 45</span>  أي  <span dir=\"ltr\" class=\"expr\">P = (x − 7)</span><sup>2</sup> <span dir=\"ltr\" class=\"expr\">− 4</span>"},{"quoi":"القاعدة","math":"الفرق بين مربّعين <span dir=\"ltr\" class=\"expr\">: a</span><sup>2</sup> <span dir=\"ltr\" class=\"expr\">− b</span><sup>2</sup> <span dir=\"ltr\" class=\"expr\">= (a − b)(a + b)</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr\">P = (x − 7)</span><sup>2</sup> <span dir=\"ltr\" class=\"expr\">− 2</span><sup>2</sup>  إذن  <span dir=\"ltr\" class=\"expr\">P = (x − 7 − 2)(x − 7 + 2)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">P = (x − 9)(x − 5)</span>"}],
